/**
 * Blocker links between issues. Reads and writes are org-scoped; cycle detection, archive rules and open/closed classification live in the service layer.
 *
 * Must call (do not reimplement): orgPredicate, livePredicate, compact
 */
import { and, asc, eq, inArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { livePredicate, orgPredicate } from "./base-repository";
import { compact } from "./_paging";
import { brandId, toIssue, toIssueDependency } from "./_mappers";
import { listLabelsForIssues } from "./label-repository";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";

export async function findDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<IssueDependency | null> {
  const row = getDb()
    .select()
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .get();
  return row ? toIssueDependency(row) : null;
}

export async function insertDependency(input: {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
  createdBy: UserId;
}): Promise<IssueDependency> {
  const row = getDb()
    .insert(issueDependencies)
    .values({
      orgId: input.orgId,
      issueId: input.issueId,
      blockerId: input.blockerId,
      createdBy: input.createdBy,
      createdAt: new Date().toISOString(),
    })
    .returning()
    .get();
  return toIssueDependency(row);
}

/** Returns whether a link existed and was removed. */
export async function deleteDependency(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const rows = getDb()
    .delete(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .returning({ issueId: issueDependencies.issueId })
    .all();
  return rows.length > 0;
}

/** Direct blockers of `issueId`, whatever their state. */
export async function listDirectBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ blockerId: issueDependencies.blockerId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
      ),
    )
    .all();
  return rows.map((row) => brandId<IssueId>(row.blockerId));
}

/** Direct dependents: the issues that `blockerId` blocks, whatever their state. */
export async function listBlockedIssueIds(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ issueId: issueDependencies.issueId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all();
  return rows.map((row) => brandId<IssueId>(row.issueId));
}

/**
 * The non-archived blocker issues of `issueId`, open and closed alike, in
 * issue-number order.
 */
export async function listLiveBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const blockerIds = getDb()
    .select({ blockerId: issueDependencies.blockerId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
      ),
    );

  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          livePredicate(issues.archivedAt, {}),
          inArray(issues.id, blockerIds),
        ),
      ),
    )
    .orderBy(asc(issues.number))
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );

  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

