import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { issueResource, requireFound } from "./_support";
import type { IssueId, OrgId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";
import type { Actor } from "@/types/member";

/** Raised when an issue is completed while at least one blocker is still open. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly blockerIds: readonly IssueId[]) {
    super(
      `Issue cannot be completed while blocked by ${blockerIds.length} open issue(s)`,
    );
    this.name = "IssueBlockedError";
  }
}

/** Raised when a new link would make an issue (transitively) block itself. */
class DependencyCycleError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: IssueId,
    readonly blockerId: IssueId,
  ) {
    super(`Issue ${issueId} cannot be blocked by ${blockerId}: it would form a cycle`);
    this.name = "DependencyCycleError";
  }
}

type BlockerLink = {
  orgId: OrgId;
  issueId: IssueId;
  blockerId: IssueId;
};

/**
 * Records "`issueId` is blocked by `blockerId`". Editing rights on the blocked
 * issue are required. Re-adding an existing link returns it unchanged.
 */
export async function addBlocker(
  actor: Actor,
  input: BlockerLink,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  // The new edge closes a cycle exactly when the blocker already (transitively)
  // depends on the blocked issue. A self-link is the zero-length case.
  if (await dependsOn(input.orgId, input.blockerId, input.issueId)) {
    throw new DependencyCycleError(input.issueId, input.blockerId);
  }

  return dependencyRepo.insertDependency({
    orgId: input.orgId,
    issueId: input.issueId,
    blockerId: input.blockerId,
    createdBy: actor.userId,
  });
}

/** Deletes the link. Resolves `false` when there was no such link. */
export async function removeBlocker(
  actor: Actor,
  input: BlockerLink,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

/** The live blockers of `issueId`, open and closed alike, by issue number. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listLiveBlockers(orgId, issueId);
}

/** Walks blocker links from `from`; true when `target` is reached (or is `from`). */
async function dependsOn(
  orgId: OrgId,
  from: IssueId,
  target: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>([from]);
  const queue: IssueId[] = [from];

  for (let current = queue.shift(); current !== undefined; current = queue.shift()) {
    if (current === target) return true;
    for (const next of await dependencyRepo.listDirectBlockerIds(orgId, current)) {
      if (!seen.has(next)) {
        seen.add(next);
        queue.push(next);
      }
    }
  }

  return false;
}

