/**
 * The unblock reaction: when a blocker closes (or is archived while still open), tell the assignee of every issue it was the last open blocker for.
 *
 * Must call (do not reimplement): subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueStatus } from "@/types/issue";
import { notify } from "./notification-service";

const isClosedStatus = (status: IssueStatus): boolean =>
  CLOSED_ISSUE_STATUSES.includes(status);

/**
 * Notifies the assignee of each live, open issue that `blockerId` blocks and
 * that no longer has any open blocker. `notify` itself skips the actor and
 * honours each recipient's preference for the kind.
 */
async function unblockDependents(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const blockedIds = await dependencyRepo.listBlockedIssueIds(orgId, blockerId);

  for (const blockedId of blockedIds) {
    const blocked = await issueRepo.findIssueById(orgId, blockedId);
    if (
      blocked === null ||
      blocked.archivedAt !== null ||
      isClosedStatus(blocked.status) ||
      blocked.assigneeId === null
    ) {
      continue;
    }

    const blockers = await dependencyRepo.listLiveBlockers(orgId, blockedId);
    if (hasOpenBlocker(blockers)) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "An issue is unblocked",
      body: `Issue ${blocked.id} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

function hasOpenBlocker(blockers: readonly Issue[]): boolean {
  return blockers.some((blocker) => !isClosedStatus(blocker.status));
}

/** Attaches the unblock reaction. Returns the detach function. */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await unblockDependents(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      // Archiving keeps the status, so the stored status is the one the
      // blocker had when it was archived.
      const archived = await issueRepo.findIssueById(payload.orgId, payload.issueId);
      if (archived === null || isClosedStatus(archived.status)) return;
      await unblockDependents(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

