mkdir -p /tmp/smoke-deps && cat > /tmp/smoke-deps/smoke.ts <<'EOF'
import { useInMemoryDb, getDb } from "@/server/db";
import { runMigrations } from "@/server/db/migrate";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as dep from "@/server/services/issue-dependency-service";
import * as issue from "@/server/services/issue-service";

useInMemoryDb();
await runMigrations(":memory:");
registerEventHandlers();
const db = getDb().$client;
const ORG = "org_a", OTHER = "org_b";
const owner = "user_owner", alice = "user_alice", bob = "user_bob";
const now = new Date().toISOString();
const mk = (id: string, num: number, status: string, assignee: string | null, org = ORG) =>
  db.prepare(`INSERT INTO issues (id, org_id, project_id, number, title, status, priority, author_id, assignee_id, created_at, updated_at) VALUES (?,?,?,?,?,?,'none',?,?,?,?)`)
    .run(id, org, "proj", num, id, status, owner, assignee, now, now);
mk("A", 1, "todo", alice);
mk("B", 2, "todo", bob);
mk("C", 3, "todo", null);
mk("X", 4, "todo", alice, OTHER);
const actor = { userId: owner, orgId: ORG, role: "owner" } as const;
const bobActor = { userId: bob, orgId: ORG, role: "member" } as const;
const ids = (xs: readonly { id: string }[]) => xs.map((x) => x.id);
const tryIt = async (label: string, fn: () => Promise<unknown>) => {
  try { const r = await fn(); console.log("OK  ", label, JSON.stringify(r)); }
  catch (e) { console.log("ERR ", label, (e as Error).name, (e as Error).message, (e as {code?:string}).code); }
};
const notes = () => db.prepare("select recipient_id, kind, href, actor_id from notifications where kind='issue_unblocked'").all();

await tryIt("add A<-B", () => dep.addBlocker(actor, { orgId: ORG as never, issueId: "A" as never, blockerId: "B" as never }));
await tryIt("add A<-B again (idempotent)", () => dep.addBlocker(actor, { orgId: ORG as never, issueId: "A" as never, blockerId: "B" as never }));
await tryIt("count rows", () => db.prepare("select count(*) c from issue_dependencies").get());
await tryIt("cycle B<-A", () => dep.addBlocker(actor, { orgId: ORG as never, issueId: "B" as never, blockerId: "A" as never }));
await tryIt("self A<-A", () => dep.addBlocker(actor, { orgId: ORG as never, issueId: "A" as never, blockerId: "A" as never }));
await tryIt("add B<-C", () => dep.addBlocker(actor, { orgId: ORG as never, issueId: "B" as never, blockerId: "C" as never }));
